export const DICT: DictEntry[] = R.map(
  ([id, ipa, pos, meaning, example, exampleFa, cat, level]) => ({
    id,
    word: id.replace(/-/g, " "),
    ipa,
    pos,
    meaning,
    example,
    exampleFa,
    cat,
    level,
  }),
);

export const ENTRY_MAP: Record<string, DictEntry> = Object.fromEntries(
  DICT.map((e) => [e.id, e]),
);

